preConditionHook:
// GUARD (2026-09-17): a level's EXISTENCE is a bool set where the scan finds
// it, never a test of the price against -1 -- a back-adjusted series can print
// -1.00 (or 0.00) as a real price. The EL twin guards on the bar index
// (SwingLowBar / SwingHighBar <> -1, VERIFIED), a count and not a price.
// Mentions of the -1 SENTINEL below describe what EL's SwingLow / SwingHigh
// return, not how this rule guards it.
// HOW MANY OF THE LAST lookback BARS TOUCHED THE SAME LEVEL AND IT HELD. Two
// sources read the same counter with opposite sign -- touches WEAKEN the level
// and favour the eventual breakout, or touches PROVE it and favour the bounce --
// so it is one rule and the placement's direction and negate toggles pick the
// reading. Defaults sit between the two sources' thresholds.
//
// THE LEVEL IS THE MOST RECENT CONFIRMED SWING PIVOT: the swing pivot low for the long
// (support) side, the swing pivot high for the short (resistance) side. The merged
// pseudocode says only "the level" and names no source for it; the pivot is the
// corpus's mechanized horizontal level, the one BreakoutLevelRetest,
// SwingPointTestHolds and SwingPivotTarget all use, so it is the one used here.
// Not TrendLineTouchCount, which counts touches of a PROJECTED SLOPING line and
// also enforces a maximum distance over the window.
//
// A TOUCH THAT HELD, on the support side, is a bar whose low came to within
// tolAtr ATRs of the level while its closing price stayed above the level less
// breakTolAtr ATRs -- the bar reached the level and did not close through it.
// Mirrored on resistance. The count runs over bars 1..lookback, EXCLUDING bar 0,
// so this bar's own test is not counted into the history that is meant to
// qualify it.
//
// ONE ATR READ, THE CURRENT ONE, for every counted bar, exactly as
// ConsecutiveClimaxBarCount and TrendLineTouchCount do. The pseudocode's
// per-bar atr[k] would be a lagged read of a WFSafe series function, which is
// not a behaviour the register covers; a single current band is the corpus's
// settled substitute and is stated here rather than assumed.
//
// Tolerances are in ATRs, not ticks -- MinMove/PriceScale are VERIFIED but the
// engine exposes no tick size to strategies.
//
// THE PIVOT SCAN IS INLINED from SwingHigh per the B-list decision, at
// Occurrence 1. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60
// min): the pivot test is MIXED -- at-or-beyond the strength OLDER bars,
// STRICTLY beyond the strength NEWER bars, and bars-ago indexing makes the
// SMALLER index the NEWER bar, so the strict half is the pk < pj loop; the
// confirmation lag is exactly strength bars, never 0 or 1, so no lookahead, and
// during the lag the PREVIOUS pivot is reported; pivotLookback is EL's Length,
// offsets 0..pivotLookback-1 inclusive, with the neighbourhood test reaching
// strength bars PAST the window; an empty window returns the -1 SENTINEL,
// guarded because -1 as a PRICE sits under every real price; the comparisons
// carry the 2.22e-12 relational tolerance. The low side's tie sense is the
// mirror of the measured high-side rule. No WFSafe_SwingLow exists, so plain EL
// governs.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator: AtrProfitTarget's
// block verbatim, including the TWO separate accumulator statements, since
// EasyLanguage evaluates Summation[1] + Price - Price[Length] left to right.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
//
// Deepest bar touched: max(lookback, pivotLookback - 1 + strength, atrLength + 1).
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLength; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLength;
} else {
    outIdx = (int)atrLength;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLength;
lvlLo = 0.0;
haveLo = false;
for (pj = (int)strength; pj <= (int)pivotLookback - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_lt(low[pj], low[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_le(low[pj], low[pk])) { pok = false; break; }
        }
    }
    if (pok) { lvlLo = low[pj]; haveLo = true; break; }
}
lvlHi = 0.0;
haveHi = false;
for (pj = (int)strength; pj <= (int)pivotLookback - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_ge(high[pj], high[pk])) { pok = false; break; }
        }
    }
    if (pok) { lvlHi = high[pj]; haveHi = true; break; }
}
touchLo = 0;
touchHi = 0;
for (kk = 1; kk <= (int)lookback; ++kk) {
    if (el_le(low[kk], lvlLo + tolAtr * atrValue) && el_gt(close[kk], lvlLo - breakTolAtr * atrValue)) {
        touchLo = touchLo + 1;
    }
    if (el_ge(high[kk], lvlHi - tolAtr * atrValue) && el_lt(close[kk], lvlHi + breakTolAtr * atrValue)) {
        touchHi = touchHi + 1;
    }
}
